INSERT INTO public.questions (materia, topico, enunciado, alternativas, correta, explicacao) VALUES
('Língua Portuguesa', 'Crase', 'Assinale a frase em que o emprego do acento indicativo de crase está correto.', '["O servidor dirigiu-se à unidade policial para registrar a ocorrência.", "A equipe chegou à pé ao local indicado.", "O relatório foi entregue à todos os presentes.", "A autoridade começou à analisar os documentos.", "O agente ficou frente à frente com a testemunha."]'::jsonb, 0, 'A expressão “dirigir-se a” rege a preposição a; diante do artigo feminino de “a unidade”, ocorre a fusão à. Não há crase antes de palavra masculina, pronome indefinido ou verbo.'),
('Língua Portuguesa', 'Regência verbal', 'De acordo com a norma-padrão, complete: “O candidato aspirava ___ cargo de escrivão.”', '["ao", "o", "pelo", "no", "do"]'::jsonb, 0, 'No sentido de desejar, “aspirar” rege a preposição a. Como “cargo” é masculino, a combinação é “ao”.'),
('Raciocínio Lógico', 'Proposições', 'A negação lógica de “Todos os relatórios foram revisados” é:', '["Nenhum relatório foi revisado.", "Pelo menos um relatório não foi revisado.", "Todos os relatórios não foram revisados.", "Alguns relatórios foram revisados.", "Apenas um relatório foi revisado."]'::jsonb, 1, 'A negação de uma afirmação universal “todo A é B” é existencial: existe ao menos um A que não é B.'),
('Raciocínio Lógico', 'Porcentagem', 'Uma equipe concluiu 40% de um levantamento na primeira semana e 30% do total na segunda. Que percentual do levantamento ainda falta?', '["20%", "25%", "30%", "40%", "70%"]'::jsonb, 2, 'As partes concluídas somam 40% + 30% = 70% do total; portanto, faltam 30%.'),
('Estatística e Análise de Dados', 'Média e mediana', 'Para os valores 2, 4, 7, 9 e 100, qual medida é menos influenciada pelo valor extremo 100?', '["Média aritmética", "Mediana", "Amplitude", "Variância", "Desvio-padrão"]'::jsonb, 1, 'A mediana é o valor central após ordenar os dados (7) e é menos sensível a valores extremos do que a média.'),
('Estatística e Análise de Dados', 'Probabilidade', 'Em uma caixa há 3 fichas azuis e 2 vermelhas. Retirando uma ficha ao acaso, qual é a probabilidade de ela ser vermelha?', '["1/5", "2/5", "3/5", "1/2", "2/3"]'::jsonb, 1, 'Há 2 resultados favoráveis entre 5 fichas equiprováveis: 2/5.'),
('Contabilidade e Análise Financeira', 'Equação patrimonial', 'Uma entidade possui ativo de R$ 80.000 e passivo exigível de R$ 25.000. Qual é o patrimônio líquido?', '["R$ 25.000", "R$ 45.000", "R$ 55.000", "R$ 80.000", "R$ 105.000"]'::jsonb, 2, 'Pela equação patrimonial, Ativo = Passivo + Patrimônio Líquido; logo, PL = 80.000 − 25.000 = R$ 55.000.'),
('Contabilidade e Análise Financeira', 'Regime de competência', 'No regime de competência, uma despesa é reconhecida, em regra:', '["Somente quando paga.", "Quando incorrida, independentemente do pagamento.", "No momento em que o caixa fica positivo.", "Apenas no encerramento do exercício.", "Quando autorizada pelo banco."]'::jsonb, 1, 'O regime de competência reconhece receitas e despesas no período a que se referem, independentemente do recebimento ou pagamento.'),
('Informática', 'Segurança da informação', 'Qual prática reduz o risco de acesso indevido a uma conta mesmo quando a senha foi descoberta?', '["Reutilizar a senha em todos os serviços.", "Desativar atualizações automáticas.", "Ativar autenticação multifator.", "Salvar a senha em arquivo público.", "Usar apenas redes Wi-Fi abertas."]'::jsonb, 2, 'A autenticação multifator exige uma segunda evidência além da senha, dificultando o acesso indevido quando a senha é comprometida.'),
('Informática', 'Planilhas eletrônicas', 'Em uma planilha, qual função é apropriada para contar células numéricas no intervalo A1:A10?', '["SOMA(A1:A10)", "MÉDIA(A1:A10)", "CONT.NÚM(A1:A10)", "MÁXIMO(A1:A10)", "TEXTO(A1:A10)"]'::jsonb, 2, 'A função CONT.NÚM (COUNT em algumas configurações) contabiliza células que contêm números.'),
('Direito Constitucional', 'Direitos e garantias fundamentais', 'Segundo a Constituição Federal, a casa é asilo inviolável, salvo, entre outras hipóteses, em caso de:', '["Ingresso policial a qualquer hora por conveniência administrativa.", "Flagrante delito, desastre ou para prestar socorro, ou durante o dia por determinação judicial.", "Determinação verbal de qualquer agente público.", "Investigação preliminar, exclusivamente à noite.", "Denúncia anônima, sem qualquer outra providência."]'::jsonb, 1, 'O art. 5º, XI, da Constituição prevê as exceções: flagrante delito, desastre, prestação de socorro e, durante o dia, determinação judicial.'),
('Direito Constitucional', 'Administração pública', 'A administração pública direta e indireta deve obedecer expressamente aos princípios de legalidade, impessoalidade, moralidade, publicidade e:', '["Economicidade.", "Eficiência.", "Hierarquia.", "Autotutela.", "Especialidade."]'::jsonb, 1, 'O caput do art. 37 da Constituição Federal enumera os princípios LIMPE: legalidade, impessoalidade, moralidade, publicidade e eficiência.'),
('Direito Administrativo', 'Atos administrativos', 'A presunção de legitimidade dos atos administrativos significa que eles:', '["São absolutamente imunes a controle judicial.", "São considerados válidos até prova em contrário, sem impedir controle.", "Não precisam respeitar a lei.", "Sempre dispensam motivação.", "Não podem ser anulados pela própria administração."]'::jsonb, 1, 'A presunção é relativa (juris tantum): admite prova em contrário e não afasta o controle administrativo ou judicial.'),
('Direito Administrativo', 'Poder de polícia', 'O poder de polícia administrativa permite à Administração, nos limites legais:', '["Criar crimes e penas por decreto.", "Condicionar ou restringir direitos e atividades em benefício do interesse público.", "Substituir o Poder Judiciário em qualquer conflito.", "Impor sanções sem processo quando a lei o exige.", "Atuar apenas sobre servidores públicos."]'::jsonb, 1, 'Poder de polícia é a atividade administrativa que limita ou disciplina direitos, interesses ou liberdades em razão do interesse público, dentro da lei.'),
('Direito Penal', 'Dolo e culpa', 'Em regra, salvo disposição expressa em contrário, o crime é punível na modalidade culposa quando:', '["O agente prevê o resultado e o deseja.", "A lei prevê expressamente a forma culposa.", "O resultado é sempre involuntário.", "Há apenas negligência, mesmo sem previsão legal.", "O agente confessa o fato."]'::jsonb, 1, 'O art. 18, parágrafo único, do Código Penal estabelece que, salvo os casos expressos em lei, ninguém pode ser punido por fato previsto como crime senão quando o pratica dolosamente.'),
('Direito Penal', 'Legítima defesa', 'Age em legítima defesa quem, usando moderadamente dos meios necessários, repele:', '["Agressão injusta, atual ou iminente, a direito próprio ou alheio.", "Qualquer crítica feita contra si.", "Agressão passada, depois de cessado o perigo.", "A ordem legal de autoridade competente.", "Todo risco hipotético, ainda que remoto."]'::jsonb, 0, 'O art. 25 do Código Penal define legítima defesa como a reação moderada, com meios necessários, contra agressão injusta atual ou iminente a direito próprio ou de terceiro.'),
('Direito Processual Penal', 'Prova', 'O exame de corpo de delito é indispensável, em regra, quando a infração:', '["Deixa vestígios.", "É exclusivamente verbal.", "É culposa.", "Foi confessada pelo investigado.", "É de menor potencial ofensivo."]'::jsonb, 0, 'Nos termos do art. 158 do CPP, quando a infração deixar vestígios, é indispensável o exame de corpo de delito, direto ou indireto; a confissão não o supre.'),
('Direito Processual Penal', 'Inquérito policial', 'O inquérito policial caracteriza-se, em regra, como procedimento:', '["Judicial, contraditório e indispensável em todos os casos.", "Administrativo, investigativo e informativo.", "Legislativo e público em todas as diligências.", "Punitivo, com aplicação direta de pena.", "Privado, conduzido pela vítima."]'::jsonb, 1, 'O inquérito é procedimento administrativo de investigação, destinado a reunir elementos informativos; não aplica pena e não é fase judicial.'),
('Legislação Penal Especial', 'Lei de Drogas', 'A Lei nº 11.343/2006 instituiu, entre outras medidas, o Sistema Nacional de Políticas Públicas sobre Drogas, conhecido pela sigla:', '["SINASE.", "SISNAD.", "SUS.", "SUSP.", "SNJ."]'::jsonb, 1, 'A Lei nº 11.343/2006 instituiu o SISNAD, Sistema Nacional de Políticas Públicas sobre Drogas.'),
('Legislação Penal Especial', 'Abuso de autoridade', 'A Lei nº 13.869/2019 exige, para os crimes de abuso de autoridade, finalidade específica de:', '["Obter vantagem ou benefício indevido, prejudicar alguém ou agir por mero capricho/satisfação pessoal, conforme a lei.", "Praticar qualquer ato administrativo irregular, ainda que sem dolo específico.", "Causar dano material exclusivamente.", "Obter vantagem econômica em todos os casos.", "Agir durante o horário de expediente."]'::jsonb, 0, 'A lei exige finalidade específica prevista no art. 1º, §1º: prejudicar alguém, beneficiar a si ou terceiro, ou agir por mero capricho ou satisfação pessoal. Divergência interpretativa, por si só, não configura abuso.'),
('Direitos Humanos', 'Tratados internacionais', 'No Brasil, tratados internacionais de direitos humanos aprovados em cada Casa do Congresso, em dois turnos, por três quintos dos votos, equivalem a:', '["Lei ordinária.", "Lei complementar.", "Emenda constitucional.", "Decreto autônomo.", "Medida provisória."]'::jsonb, 2, 'O art. 5º, §3º, da Constituição atribui equivalência às emendas constitucionais aos tratados de direitos humanos aprovados pelo rito qualificado ali previsto.'),
('Direitos Humanos', 'Universalidade', 'O princípio da universalidade dos direitos humanos indica que esses direitos são reconhecidos:', '["Somente a cidadãos de países democráticos.", "A todas as pessoas, sem discriminação, por sua condição humana.", "Apenas a quem possui capacidade civil plena.", "Somente a grupos definidos pelo Estado.", "Exclusivamente a pessoas em território nacional."]'::jsonb, 1, 'A universalidade afirma que os direitos humanos pertencem a todas as pessoas, sem discriminação, embora sua proteção ocorra em contextos jurídicos diversos.'),
('Criminologia', 'Objeto de estudo', 'A criminologia é tradicionalmente compreendida como ciência empírica e interdisciplinar que estuda crime, criminoso, vítima e:', '["Pena em abstrato, exclusivamente.", "Controle social.", "Somente o processo legislativo.", "Apenas estatísticas policiais.", "A validade formal das leis."]'::jsonb, 1, 'A concepção tradicional da criminologia abrange quatro objetos: delito, delinquente, vítima e controle social.'),
('Criminologia', 'Prevenção criminal', 'A prevenção terciária da criminalidade dirige-se principalmente:', '["À população em geral, antes de qualquer risco identificado.", "A grupos em situação de risco, sem ocorrência de infração.", "À pessoa que já praticou infração, buscando evitar reincidência e favorecer reinserção.", "À elaboração abstrata de tipos penais.", "À vítima, exclusivamente para reparação civil."]'::jsonb, 2, 'A prevenção terciária atua após o delito, especialmente sobre o autor, com foco em evitar reincidência e apoiar reintegração social.'),
('História e Geografia do Amapá', 'Geografia do Amapá', 'Qual é a capital do estado do Amapá?', '["Santana", "Oiapoque", "Macapá", "Laranjal do Jari", "Mazagão"]'::jsonb, 2, 'Macapá é a capital do Amapá e está situada às margens do rio Amazonas.'),
('História e Geografia do Amapá', 'Limites estaduais', 'O estado do Amapá faz fronteira internacional com:', '["Guiana Francesa e Suriname.", "Guiana Francesa e Guiana.", "Suriname e Venezuela.", "Colômbia e Guiana Francesa.", "Venezuela e Guiana."]'::jsonb, 0, 'O Amapá limita-se ao norte com a Guiana Francesa e, em trecho menor, com o Suriname; também faz fronteira estadual com o Pará e é banhado pelo Atlântico.'),
('Legislação Estadual (PC-AP)', 'Segurança pública', 'Nos termos do art. 144 da Constituição Federal, às polícias civis, dirigidas por delegados de polícia de carreira, incumbem, ressalvada a competência da União, as funções de:', '["Polícia ostensiva e preservação da ordem pública.", "Polícia judiciária e apuração de infrações penais, exceto as militares.", "Defesa externa e soberania nacional.", "Polícia ferroviária federal.", "Execução de penas privativas de liberdade."]'::jsonb, 1, 'O art. 144, §4º, da CF atribui às polícias civis, ressalvada a competência da União, as funções de polícia judiciária e apuração de infrações penais, exceto as militares.'),
('Legislação Estadual (PC-AP)', 'Princípios institucionais', 'A organização e atuação da Polícia Civil estadual devem respeitar, entre outros, os direitos e garantias previstos:', '["Na Constituição Federal e na legislação aplicável.", "Apenas em regulamento interno.", "Somente em atos administrativos sigilosos.", "Em ordens individuais, ainda que contrárias à lei.", "Exclusivamente em normas municipais."]'::jsonb, 0, 'Órgãos estaduais de segurança pública estão subordinados à Constituição Federal e às normas legais aplicáveis; regulamentos internos não podem afastar direitos fundamentais.'),
('Direito Civil/Empresarial e Legislação Complementar', 'Negócios jurídicos', 'São requisitos de validade do negócio jurídico, conforme o Código Civil:', '["Agente capaz, objeto lícito, possível, determinado ou determinável e forma prescrita ou não defesa em lei.", "Agente maior de 21 anos, objeto lucrativo e forma escrita.", "Duas testemunhas, registro público e objeto presente.", "Autorização judicial em qualquer hipótese.", "Agente capaz e objeto lícito, sendo sempre exigida escritura pública."]'::jsonb, 0, 'O art. 104 do Código Civil estabelece agente capaz, objeto lícito, possível, determinado ou determinável e forma prescrita ou não defesa em lei.'),
('Direito Civil/Empresarial e Legislação Complementar', 'Responsabilidade civil', 'Em regra, aquele que, por ato ilícito, causar dano a outrem fica obrigado a:', '["Repará-lo.", "Pagar multa criminal automaticamente.", "Indenizar apenas se houver contrato.", "Reparar somente dano material.", "Aguardar condenação criminal transitada em julgado em todos os casos."]'::jsonb, 0, 'O art. 927 do Código Civil prevê o dever de reparar o dano causado por ato ilícito, observadas as regras legais aplicáveis.'),
('Direito Tributário e Legislação Complementar', 'Espécies tributárias', 'Segundo o Código Tributário Nacional, tributo é prestação pecuniária compulsória que:', '["Constitui sanção por ato ilícito.", "Não constitui sanção por ato ilícito e é instituída em lei.", "Pode ser exigida sem previsão legal.", "É sempre cobrada por serviço público específico.", "Depende de acordo individual com o contribuinte."]'::jsonb, 1, 'O art. 3º do CTN define tributo como prestação pecuniária compulsória, em moeda ou valor exprimível, que não constitua sanção de ato ilícito, instituída em lei e cobrada mediante atividade administrativa vinculada.'),
('Direito Tributário e Legislação Complementar', 'Impostos', 'A característica que distingue, em regra, o imposto das taxas é que o imposto:', '["Tem como fato gerador uma atuação estatal específica relativa ao contribuinte.", "Independe de contraprestação estatal específica e divisível.", "Só pode ser instituído por município.", "É sempre vinculado a obra pública.", "É tributo facultativo."]'::jsonb, 1, 'Impostos não estão vinculados a uma atividade estatal específica relativa ao contribuinte; taxas decorrem do exercício do poder de polícia ou de serviço público específico e divisível.'),
('Direito Ambiental e Legislação Complementar', 'Responsabilidade ambiental', 'A responsabilidade civil por dano ambiental é, conforme a legislação e a jurisprudência brasileiras, em regra:', '["Subjetiva e depende sempre de prova de culpa.", "Objetiva, sem prejuízo das responsabilidades administrativa e penal cabíveis.", "Exclusivamente penal.", "Aplicável apenas a pessoas jurídicas públicas.", "Inexistente quando houver licença ambiental."]'::jsonb, 1, 'A responsabilidade civil ambiental é objetiva, conforme art. 14, §1º, da Lei nº 6.938/1981, e pode coexistir com as esferas administrativa e penal.'),
('Direito Ambiental e Legislação Complementar', 'Princípios ambientais', 'O princípio da prevenção relaciona-se principalmente:', '["A riscos conhecidos ou identificáveis, buscando evitar a ocorrência do dano.", "A danos já consumados, sem possibilidade de reparação.", "À dispensa de licenciamento.", "À transferência do dever de proteção exclusivamente ao cidadão.", "À proibição de qualquer atividade econômica."]'::jsonb, 0, 'A prevenção orienta a adoção de medidas diante de riscos conhecidos ou comprovados; a precaução é especialmente associada à incerteza científica relevante.'),
('Medicina Legal', 'Traumatologia forense', 'Uma equimose é produzida, em regra, por:', '["Ruptura de vasos com infiltração de sangue nos tecidos, sem solução de continuidade da pele.", "Corte linear com bordas regulares.", "Perda completa de segmento corporal.", "Ação exclusiva de calor.", "Perfuração de cavidade por objeto pontiagudo."]'::jsonb, 0, 'Equimose é infiltração hemorrágica nos tecidos por ruptura de vasos, geralmente causada por ação contundente, mantendo-se a pele íntegra.'),
('Medicina Legal', 'Tanatologia', 'A rigidez cadavérica (rigor mortis) decorre principalmente:', '["Da coagulação do sangue nas artérias.", "De alterações bioquímicas musculares após a morte, com depleção de ATP.", "Da evaporação da água da pele.", "Da ação imediata de bactérias externas.", "Da queda da temperatura corporal exclusivamente."]'::jsonb, 1, 'Após a morte, a depleção de ATP impede o relaxamento das pontes actina-miosina, contribuindo para a rigidez muscular cadavérica.')
